//! `versions.lock`: one pinned download per line.

use std::fs;
use std::path::{Path, PathBuf};

use crate::{Error, Platform, read_to_string};

const LOCK_HEADER: &str = "# Generated by `bazel run //tools/bootstrap/lock` from versions.toml.\n\
                           # Do not edit. Columns: component, platform, SHA-256, URL.\n";

/// One line of `versions.lock`.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Pin {
    pub component: String,
    /// A platform name, or `any` for files every platform installs.
    pub platform: String,
    pub sha256: String,
    pub url: String,
}

impl Pin {
    pub fn new(component: &str, platform: &str, sha256: String, url: String) -> Self {
        Pin {
            component: component.to_owned(),
            platform: platform.to_owned(),
            sha256,
            url,
        }
    }

    pub fn applies_to(&self, platform: Platform) -> bool {
        self.platform == "any" || self.platform == platform.name()
    }

    /// The file name at the end of the URL.
    pub(crate) fn file_name(&self) -> &str {
        self.url.rsplit('/').next().unwrap_or(&self.url)
    }
}

pub fn read_lock(dir: &Path) -> Result<Vec<Pin>, Error> {
    let path = dir.join("versions.lock");
    parse_lock(&path, &read_to_string(&path)?)
}

fn parse_lock(path: &Path, text: &str) -> Result<Vec<Pin>, Error> {
    text.lines()
        .enumerate()
        .filter(|(_, line)| !line.starts_with('#') && !line.trim().is_empty())
        .map(
            |(index, line)| match line.split_whitespace().collect::<Vec<_>>()[..] {
                [component, platform, sha256, url] => Ok(Pin {
                    component: component.to_owned(),
                    platform: platform.to_owned(),
                    sha256: sha256.to_owned(),
                    url: url.to_owned(),
                }),
                _ => Err(Error::MalformedLock {
                    path: path.to_owned(),
                    line: index + 1,
                }),
            },
        )
        .collect()
}

pub fn write_lock(dir: &Path, pins: &[Pin]) -> Result<PathBuf, Error> {
    let mut lock = String::from(LOCK_HEADER);
    for pin in pins {
        lock.push_str(&format!(
            "{} {} {} {}\n",
            pin.component, pin.platform, pin.sha256, pin.url
        ));
    }
    let path = dir.join("versions.lock");
    fs::write(&path, lock).map_err(|source| Error::Write {
        path: path.clone(),
        source,
    })?;
    Ok(path)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn malformed_lock_names_the_line() {
        let error = parse_lock(
            Path::new("versions.lock"),
            "# header\nbazelisk darwin-arm64 abc\n",
        )
        .unwrap_err();
        assert!(
            matches!(error, Error::MalformedLock { line: 2, .. }),
            "{error}"
        );
    }
}
